package com.bank.risk;

import java.math.BigInteger;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FactorialDemo {

    private static final Logger log = Logger.getLogger(FactorialDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FactorialCalculator calculator = new FactorialCalculator();

        for (int n : new int[]{0, 5, 13, 21}) {
            BigInteger result = calculator.factorial(n);
            log.info(() -> "Orderings of " + n + " risk events = " + n + "! = " + result);
        }

        // Demonstrate that negative input is rejected.
        try {
            calculator.factorial(-3);
        } catch (IllegalArgumentException ex) {
            log.log(Level.SEVERE, "Rejected invalid input", ex);
        }
    }
}

// ─── Would be in service/FactorialCalculator.java in a real project ───
class FactorialCalculator {

    private static final Logger log = Logger.getLogger(FactorialCalculator.class.getName());

    // Recursive factorial using BigInteger so it never overflows.
    BigInteger factorial(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Factorial not defined for negative numbers: " + n);
        }
        // BASE CASE: fact(0) = 1. Stops the recursion.
        if (n == 0) {
            return BigInteger.ONE;
        }
        // RECURSIVE CASE: fact(n) = n * fact(n-1).
        log.fine(() -> "Computing " + n + " * fact(" + (n - 1) + ")");
        return BigInteger.valueOf(n).multiply(factorial(n - 1));
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
